typedef int (*guard_fn)(struct request *r);
static const guard_fn guards[] = { authenticate, authorize, valid_session, valid_input };

int secure_dispatch(struct request *r, const struct action *a) {
    for (size_t i = 0; i < sizeof guards / sizeof *guards; i++)
        if (!guards[i](r)) return deny(r);
    audit(r);
    return a->business(r);   /* the only way to an action */
}
